local classes = {}

classes.BadRequest = errors.define({
  tag = "BadRequest",
  categories = { "BadRequestError" },
  matchers = { { status = 400 } },
  fields = { "code", "message" },
})
classes.ContainerApplicationCreateUnavailable = errors.define({
  tag = "ContainerApplicationCreateUnavailable",
  categories = {},
  matchers = { { message = { includes = "can't create application at this time" } } },
  fields = { "code", "message" },
})
classes.ContainerApplicationNotFound = errors.define({
  tag = "ContainerApplicationNotFound",
  categories = {},
  matchers = {
    { code = 1609, message = { includes = "Container application not found" } },
    { code = 1609, message = { includes = "APPLICATION_NOT_FOUND" } },
  },
  fields = { "code", "message" },
})
classes.ContainerImagePreparationInvalidImage = errors.define({
  tag = "ContainerImagePreparationInvalidImage",
  categories = { "BadRequestError" },
  matchers = {
    {
      code = 1000,
      status = 400,
      message = {
        includes = "image must be digest-pinned and hosted in a supported managed registry",
      },
    },
    { code = 1000, status = 400, message = { includes = "image does not exist in this account" } },
  },
  fields = { "code", "message" },
})
classes.DurableObjectAlreadyHasApplication = errors.define({
  tag = "DurableObjectAlreadyHasApplication",
  categories = {},
  matchers = { { code = 1608, message = { includes = "DURABLE_OBJECT_ALREADY_HAS_APPLICATION" } } },
  fields = { "code", "message" },
})
classes.DurableObjectCheckError = errors.define({
  tag = "DurableObjectCheckError",
  categories = {},
  matchers = {
    { code = 1000, message = { includes = "checking the application durable object" } },
  },
  fields = { "code", "message" },
})
classes.DurableObjectNamespaceNotFound = errors.define({
  tag = "DurableObjectNamespaceNotFound",
  categories = {},
  matchers = {
    { status = 400, message = { includes = "Durable Object namespace was not found" } },
  },
  fields = { "code", "message" },
})
classes.DurableObjectNotContainerEnabled = errors.define({
  tag = "DurableObjectNotContainerEnabled",
  categories = {},
  matchers = { { code = 1607, message = { includes = "DURABLE_OBJECT_NOT_CONTAINER_ENABLED" } } },
  fields = { "code", "message" },
})
classes.Forbidden = errors.define({
  tag = "Forbidden",
  categories = { "AuthError" },
  matchers = { { status = 403 } },
  fields = { "code", "message" },
})
classes.InvalidRoute = errors.define({
  tag = "InvalidRoute",
  categories = {},
  matchers = { { code = 7003, message = { includes = "Could not route" } } },
  fields = { "code", "message" },
})

